/* SPDX-License-Identifier: AGPL-3.0-only */
@import "tailwindcss";
@import "./theme.css";
@import "golden-layout/dist/css/goldenlayout-base.css";
@import "golden-layout/dist/css/themes/goldenlayout-dark-theme.css";
@plugin "@tailwindcss/typography";

#navbar {
  position: relative !important;
  z-index: var(--z-base) !important;
  pointer-events: auto !important;
}

#navbar button,
#navbar [role="button"],
#navbar a,
#navbar [role="link"],
#navbar input,
#navbar select,
#navbar textarea {
  pointer-events: auto !important;
  -webkit-app-region: no-drag !important;
}

#navbar {
  -webkit-app-region: drag !important;
}

.lm_goldenlayout {
  background-color: var(--base) !important;
  color: var(--foreground) !important;
  z-index: var(--z-base) !important;
  position: relative !important;
  pointer-events: auto !important;
  overflow: hidden !important;
}

.lm_goldenlayout * {
  pointer-events: auto !important;
}

.lm_root {
  z-index: var(--z-base) !important;
  position: relative !important;
  overflow: hidden !important;
}

.lm_item {
  z-index: var(--z-base) !important;
  position: relative !important;
  box-sizing: border-box !important;
}

.lm_header,
.lm_tabs,
.lm_controls {
  z-index: var(--z-panel) !important;
}

.lm_header {
  display: flex !important;
  visibility: visible !important;
  height: 20px !important;
  min-height: 20px !important;
  max-height: 20px !important;
  opacity: 1 !important;
  z-index: var(--z-panel) !important;
  position: relative !important;
  background-color: transparent !important;
  border-bottom: 1px solid var(--border-color) !important;
}

.lm_tabs {
  display: flex !important;
  visibility: visible !important;
  opacity: 1 !important;
  flex: 1 !important;
  background-color: transparent !important;
}

.lm_tab {
  display: flex !important;
  visibility: visible !important;
  opacity: 1 !important;
  background-color: var(--window) !important;
  color: var(--foreground) !important;
  padding: 2px 8px !important;
  cursor: var(--cursor-pointer) !important;
  border-top: 1px solid var(--border-color) !important;
  border-right: 1px solid var(--border-color) !important;
  user-select: none !important;
  -webkit-user-select: none !important;
  margin-bottom: -1px !important;
  padding-bottom: 3px !important;
}

.lm_tab:hover {
  background-color: var(--hover-window) !important;
}

.lm_tab.lm_active {
  background-color: var(--window) !important;
  color: var(--foreground) !important;
}

.lm_title {
  opacity: 1 !important;
  visibility: visible !important;
  color: var(--foreground) !important;
  font-size: var(--text-xs) !important;
  line-height: var(--text-xs--line-height) !important;
}

.lm_controls {
  display: flex !important;
  visibility: visible !important;
  opacity: 1 !important;
  flex-shrink: 0 !important;
  background-color: transparent !important;
}

.lm_close_tab {
  display: none !important;
  visibility: hidden !important;
}

.lm_popout,
.lm_maximise,
.lm_close {
  display: none !important;
  visibility: hidden !important;
}

.lm_popout:hover,
.lm_maximise:hover,
.lm_close:hover {
  background-color: transparent !important;
}

.lm_popout::before {
  content: "□" !important;
  display: block !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  color: var(--foreground) !important;
  font-size: 10px !important;
  line-height: 1 !important;
}

.lm_maximise::before {
  content: "■" !important;
  display: block !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  color: var(--foreground) !important;
  font-size: 8px !important;
  line-height: 1 !important;
}

.lm_close::before {
  content: "×" !important;
  display: block !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  color: var(--foreground) !important;
  font-size: 14px !important;
  line-height: 1 !important;
  font-weight: bold !important;
}

.lm_item.lm_stack {
  border: none !important;
  position: relative !important;
  background-color: transparent !important;
}

.lm_item.lm_stack::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  box-shadow:
    inset 1px 0 0 0 var(--border-color),
    inset -1px 0 0 0 var(--border-color),
    inset 0 -1px 0 0 var(--border-color) !important;
  z-index: var(--z-panel) !important;
  pointer-events: none !important;
}

.lm_item.lm_component {
  border: none !important;
  box-shadow: none !important;
  background-color: var(--window) !important;
}

.lm_content {
  border: none !important;
  background-color: var(--window) !important;
}

.lm_items {
  border: none !important;
}

.lm_splitter {
  background-color: var(--base) !important;
}
.lm_splitter.lm_splitter_vertical {
  width: var(--spacing-single) !important;
  min-width: var(--spacing-single) !important;
  cursor: var(--cursor-ew-resize) !important;
}
.lm_splitter.lm_splitter_horizontal {
  height: var(--spacing-single) !important;
  min-height: var(--spacing-single) !important;
  cursor: var(--cursor-ns-resize) !important;
}

.lm_splitter:hover {
  background-color: var(--border-element-color) !important;
}

/* https://tailwindcss.com/docs/theme */
/* https://ui.shadcn.com/docs/theming */

.body {
}

/* Set base all components */
@layer base {
  :root {
    --radius: 0rem;
    --radius-xs: 0rem;
    --radius-sm: 0rem;
    --radius-md: 0rem;
    --radius-lg: 0rem;
    --radius-xl: 0rem;
    --radius-2xl: 0rem;
    --radius-3xl: 0rem;
    --radius-4xl: 0rem;
    --radius-full: 0rem;
    --shadow-2xs: 0 0 rgb(0 0 0 / 0);
    --shadow-xs: 0 0 rgb(0 0 0 / 0);
    --shadow-sm: 0 0 rgb(0 0 0 / 0);
    --shadow-md: 0 0 rgb(0 0 0 / 0);
    --shadow-lg: 0 0 rgb(0 0 0 / 0);
    --shadow-xl: 0 0 rgb(0 0 0 / 0);
    --shadow-2xl: 0 0 rgb(0 0 0 / 0);
    --inset-shadow-2xs: inset 0 0 rgb(0 0 0 / 0);
    --inset-shadow-xs: inset 0 0 rgb(0 0 0 / 0);
    --inset-shadow-sm: inset 0 0 rgb(0 0 0 / 0);
    --drop-shadow-xs: 0 0 rgb(0 0 0 / 0);
    --drop-shadow-sm: 0 0 rgb(0 0 0 / 0);
    --drop-shadow-md: 0 0 rgb(0 0 0 / 0);
    --drop-shadow-lg: 0 0 rgb(0 0 0 / 0);
    --drop-shadow-xl: 0 0 rgb(0 0 0 / 0);
    --drop-shadow-2xl: 0 0 rgb(0 0 0 / 0);
    --spacing-compact: 0.2rem;
    --spacing-touch: 0.275rem;
    --spacing: var(--spacing-compact);
    --spacing-single: calc(1 * var(--spacing));
    --spacing-double: calc(2 * var(--spacing));
    --size-tiny: calc(3 * var(--spacing));
    --size-small: calc(5 * var(--spacing));
    --size-workbench: calc(1.5 * var(--size-small));
    --size-medium: calc(7 * var(--spacing));
    --size-large: calc(9 * var(--spacing));
    --size-huge: calc(11 * var(--spacing));
    --size-mega: calc(13 * var(--spacing));
    --size-giga: calc(15 * var(--spacing));
    --toolbar-item-height: var(--size-medium);
    --toolbar-gap: var(--spacing-single);
    --toolbar-group-gap: var(--spacing-double);
    --toolbar-padding-inline: var(--spacing-single);
    --toolbar-divider-height: var(--size-small);
    --text-2xs: 0.6rem;
    --text-2xs--line-height: calc(0.9 / 0.6);
    --text-xs: 0.7rem;
    --text-xs--line-height: calc(1 / 0.7);
    --text-sm: 0.8rem;
    --text-sm--line-height: calc(1.2 / 0.8);
    --text-base: 0.9rem;
    --text-base--line-height: calc(1.4 / 0.9);
    --text-lg: 1rem;
    --text-lg--line-height: calc(1.6 / 1);
    --text-xl: 1.125rem;
    --text-xl--line-height: calc(1.6 / 1.125);
    --text-2xl: 1.35rem;
    --text-2xl--line-height: calc(1.9 / 1.35);
    --text-3xl: 1.7rem;
    --text-3xl--line-height: calc(2.1 / 1.7);
    --text-4xl: 2rem;
    --text-4xl--line-height: calc(2.3 / 2);
    --text-5xl: 2.7rem;
    --text-5xl--line-height: 1;
    --text-6xl: 3.4rem;
    --text-6xl--line-height: 1;
    --text-7xl: 4rem;
    --text-7xl--line-height: 1;
    --text-8xl: 5.4rem;
    --text-8xl--line-height: 1;
    --text-9xl: 7.2rem;
    --text-9xl--line-height: 1;
    --base: var(--color-light);
    --window: var(--color-light-6-7);
    --panel: var(--color-light-5-7);
    --overlay: transparent;
    --temporary: var(--color-light-4-7);
    --foreground: var(--color-dark);
    --z-base: 0;
    --z-window: 5;
    --z-panel: 10;
    --z-overlay: 20;
    --z-temporary: 30;
    --z-navbar: 100;
    --z-modal: 1000;
    --z-tutorial: 10000;
    --muted: var(--color-light-8-9);
    --muted-foreground: var(--color-gray);
    --accent: var(--color-primary);
    --accent-secondary: var(--color-secondary);
    --accent-tertiary: var(--color-tertiary);
    --accent-foreground: var(--color-dark);
    --hover-base: var(--color-gray-700);
    --hover-window: var(--color-light-gray);
    --hover-panel: var(--color-gray-600);
    --hover-overlay: var(--color-gray-600);
    --hover-temporary: var(--color-light-gray-gray);
    --active-base: var(--color-primary);
    --active-foreground: var(--color-dark);
    --border-window-color: var(--color-gray);
    --border-element-color: var(--color-gray);
    --border-color: var(--border-window-color);
    --plaster: var(--color-gray);
    --plaster-edge: var(--color-foreground);
    --info-bg: var(--color-light-8-9);
    --info-foreground: var(--color-dark);
    --info-border: var(--color-info);
    --success-bg: var(--color-light-7-9);
    --success-foreground: var(--color-dark);
    --success-border: var(--color-success);
    --warning-bg: var(--color-light-6-7);
    --warning-foreground: var(--color-dark);
    --warning-border: var(--color-warning);
    --destructive-bg: var(--color-light-8-9);
    --destructive-foreground: var(--color-danger);
    --destructive-border: var(--color-danger);
    --color-new: var(--success-border);
    --color-modified: var(--warning-border);
    --color-removed: var(--destructive-border);
    --color-changed-selected: var(--accent);
    --color-changed-hovered: var(--accent-secondary);
    --cursor-default: url("../../semio/assets/cursors/cursor.svg") 0 0, default;
    --cursor-pointer: url("../../semio/assets/cursors/cursor_pointer.svg") 0 0, pointer;
    --cursor-grab: url("../../semio/assets/cursors/cursor_grab.svg") 0 0, grab;
    --cursor-grabbing: url("../../semio/assets/cursors/cursor_grabbing.svg") 0 0, grabbing;
    --cursor-ew-resize: url("../../semio/assets/cursors/cursor_ew-resize.svg") 16 2, ew-resize;
    --cursor-col-resize: url("../../semio/assets/cursors/cursor_ew-resize.svg") 16 2, col-resize;
    --cursor-ns-resize: url("../../semio/assets/cursors/cursor_ns-resize.svg") 2 16, ns-resize;
    --cursor-nesw-resize: url("../../semio/assets/cursors/cursor_nesw-resize_dark.svg") 16 16, nesw-resize;
    --cursor-nwse-resize: url("../../semio/assets/cursors/cursor_nwse-resize.svg") 16 16, nwse-resize;
    --cursor-move: url("../../semio/assets/cursors/cursor_move_inkscape.svg") 16 16, move;
    --cursor-crosshair: url("../../semio/assets/cursors/cursor_crosshair.svg") 0 0, crosshair;
    --cursor-crosshair-centered: url("../../semio/assets/cursors/cursor_crosshair.svg") 16 16, crosshair;
    --cursor-selectable: url("../../semio/assets/cursors/cursor_selectable.svg") 0 0, pointer;
    --cursor-foldable: url("../../semio/assets/cursors/cursor_foldable.svg") 0 0, pointer;
    --cursor-help: help;
    --cursor-not-allowed: url("../../semio/assets/cursors/cursor_not-allowed.svg") 0 0, not-allowed;
    --cursor-text: text;
    * {
      cursor: var(--cursor-default);
    }

    ::selection {
      background-color: var(--accent);
    }

    ::-moz-selection {
      background-color: var(--accent);
    }

    body.cursor-selectable {
      cursor: var(--cursor-selectable) !important;
    }

    body.cursor-selectable * {
      cursor: var(--cursor-selectable) !important;
    }

    .cursor-default,
    [style*="cursor: default"],
    [style*="cursor:default"],
    [class*="cursor-default"],
    [class*="before:cursor-default"]::before,
    [class*="after:cursor-default"]::after {
      cursor: var(--cursor-default) !important;
    }

    .cursor-pointer,
    [style*="cursor: pointer"],
    [style*="cursor:pointer"],
    [class*="cursor-pointer"],
    [class*="before:cursor-pointer"]::before,
    [class*="after:cursor-pointer"]::after {
      cursor: var(--cursor-pointer) !important;
    }

    .cursor-selectable,
    [style*="cursor: selectable"],
    [style*="cursor:selectable"],
    [class*="cursor-selectable"],
    [class*="before:cursor-selectable"]::before,
    [class*="after:cursor-selectable"]::after {
      cursor: var(--cursor-selectable) !important;
    }

    .cursor-foldable,
    [style*="cursor: foldable"],
    [style*="cursor:foldable"],
    [class*="cursor-foldable"],
    [class*="before:cursor-foldable"]::before,
    [class*="after:cursor-foldable"]::after {
      cursor: var(--cursor-foldable) !important;
    }

    .cursor-grab,
    [style*="cursor: grab"],
    [style*="cursor:grab"],
    [class*="cursor-grab"],
    [class*="before:cursor-grab"]::before,
    [class*="after:cursor-grab"]::after {
      cursor: var(--cursor-grab) !important;
    }

    .cursor-grabbing,
    [style*="cursor: grabbing"],
    [style*="cursor:grabbing"],
    [class*="cursor-grabbing"],
    [class*="before:cursor-grabbing"]::before,
    [class*="after:cursor-grabbing"]::after {
      cursor: var(--cursor-grabbing) !important;
    }

    .cursor-ew-resize,
    [style*="cursor: ew-resize"],
    [style*="cursor:ew-resize"],
    [class*="cursor-ew-resize"],
    [class*="before:cursor-ew-resize"]::before,
    [class*="after:cursor-ew-resize"]::after {
      cursor: var(--cursor-ew-resize) !important;
    }

    .cursor-col-resize,
    [style*="cursor: col-resize"],
    [style*="cursor:col-resize"],
    [class*="cursor-col-resize"],
    [class*="before:cursor-col-resize"]::before,
    [class*="after:cursor-col-resize"]::after {
      cursor: var(--cursor-col-resize) !important;
    }

    .cursor-ns-resize,
    [style*="cursor: ns-resize"],
    [style*="cursor:ns-resize"],
    [class*="cursor-ns-resize"],
    [class*="before:cursor-ns-resize"]::before,
    [class*="after:cursor-ns-resize"]::after {
      cursor: var(--cursor-ns-resize) !important;
    }

    .cursor-nesw-resize,
    [style*="cursor: nesw-resize"],
    [style*="cursor:nesw-resize"],
    [class*="cursor-nesw-resize"],
    [class*="before:cursor-nesw-resize"]::before,
    [class*="after:cursor-nesw-resize"]::after {
      cursor: var(--cursor-nesw-resize) !important;
    }

    .cursor-nwse-resize,
    [style*="cursor: nwse-resize"],
    [style*="cursor:nwse-resize"],
    [class*="cursor-nwse-resize"],
    [class*="before:cursor-nwse-resize"]::before,
    [class*="after:cursor-nwse-resize"]::after {
      cursor: var(--cursor-nwse-resize) !important;
    }

    .cursor-move,
    [style*="cursor: move"],
    [style*="cursor:move"],
    [class*="cursor-move"],
    [class*="before:cursor-move"]::before,
    [class*="after:cursor-move"]::after {
      cursor: var(--cursor-move) !important;
    }

    .cursor-crosshair,
    [style*="cursor: crosshair"],
    [style*="cursor:crosshair"],
    [class*="cursor-crosshair"],
    [class*="before:cursor-crosshair"]::before,
    [class*="after:cursor-crosshair"]::after {
      cursor: var(--cursor-crosshair) !important;
    }

    .cursor-not-allowed,
    [class~="cursor-not-allowed"],
    [style*="cursor: not-allowed"],
    [style*="cursor:not-allowed"] {
      cursor: var(--cursor-not-allowed) !important;
    }

    [class*="cursor-not-allowed"]:is(:disabled, [aria-disabled="true"], [data-disabled="true"]) {
      cursor: var(--cursor-not-allowed) !important;
    }

    .cursor-help,
    [style*="cursor: help"],
    [style*="cursor:help"],
    [class*="cursor-help"],
    [class*="before:cursor-help"]::before,
    [class*="after:cursor-help"]::after {
      cursor: var(--cursor-help) !important;
    }

    .cursor-text,
    [style*="cursor: text"],
    [style*="cursor:text"],
    [class*="cursor-text"],
    [class*="before:cursor-text"]::after {
      cursor: var(--cursor-text) !important;
    }

    .react-flow__node:not(.cursor-pointer):not(.cursor-foldable):not(.cursor-grab):not(.cursor-grabbing):not(.cursor-move):not(.cursor-crosshair):not(.cursor-not-allowed):not(.cursor-help):not(.cursor-text) {
      cursor: var(--cursor-selectable) !important;
    }

    .react-flow__edge {
      cursor: var(--cursor-pointer) !important;
    }

    .react-flow__pane.draggable {
      cursor: var(--cursor-grab) !important;
    }
    .react-flow__pane.dragging {
      cursor: var(--cursor-grabbing) !important;
    }
    .react-flow__handle.connectionindicator {
      cursor: var(--cursor-crosshair-centered) !important;
    }

    .temp .react-flow__edge-path {
      stroke: #e98787;
      stroke-dasharray: 5 5;
    }

    .react-flow__handle.connectionindicator,
    .react-flow__handle.connectionindicator:hover {
      cursor: var(--cursor-crosshair-centered) !important;
    }

    .react-flow__viewport-portal {
      pointer-events: none !important;
    }

    [data-slot="popover-trigger"] {
      cursor: var(--cursor-pointer) !important;
    }

    [data-slot="resizable-handle"][data-panel-group-direction="horizontal"],
    [data-slot="resizable-handle"][data-panel-group-direction="horizontal"]::before,
    [data-slot="resizable-handle"][data-panel-group-direction="horizontal"]::after {
      cursor: var(--cursor-ew-resize) !important;
    }

    [data-slot="resizable-handle"][data-panel-group-direction="vertical"],
    [data-slot="resizable-handle"][data-panel-group-direction="vertical"]::before,
    [data-slot="resizable-handle"][data-panel-group-direction="vertical"]::after {
      cursor: var(--cursor-ns-resize) !important;
    }

    [role="button"]:not(.cursor-selectable):not(.cursor-foldable):not(.cursor-grab):not(.cursor-grabbing):not(.cursor-move):not(.cursor-crosshair):not(.cursor-not-allowed):not(.cursor-help):not(.cursor-text),
    [role="link"]:not(.cursor-selectable):not(.cursor-foldable):not(.cursor-grab):not(.cursor-grabbing):not(.cursor-move):not(.cursor-crosshair):not(.cursor-not-allowed):not(.cursor-help):not(.cursor-text),
    a:not(.cursor-selectable):not(.cursor-foldable):not(.cursor-grab):not(.cursor-grabbing):not(.cursor-move):not(.cursor-crosshair):not(.cursor-not-allowed):not(.cursor-help):not(.cursor-text),
    button:not(.cursor-selectable):not(.cursor-foldable):not(.cursor-grab):not(.cursor-grabbing):not(.cursor-move):not(.cursor-crosshair):not(.cursor-not-allowed):not(.cursor-help):not(.cursor-text) {
      cursor: var(--cursor-pointer) !important;
    }

    [data-slot="breadcrumb-link"],
    [data-slot="breadcrumb-separator"][class*="cursor-pointer"] {
      cursor: var(--cursor-pointer) !important;
    }

    [data-slot="toolbar-zone"] [data-slot="toggle-group"],
    [data-slot="toolbar-zone"] [data-slot="button-group"] {
      border-width: 0;
      height: 100%;
    }

    [data-slot="toolbar-zone"] [data-slot="toggle-group-item"],
    [data-slot="toolbar-zone"] [data-slot="button-group-item"] {
      height: 100%;
    }
  }
}

.dark {
  --base: var(--color-dark);
  --window: var(--color-dark-8-9);
  --panel: var(--color-dark-7-9);
  --overlay: transparent;
  --temporary: var(--color-dark-gray);
  --foreground: var(--color-light);
  --active-base: var(--color-primary);
  --active-foreground: var(--color-light);
  --muted: var(--color-dark-8-9);
  --muted-foreground: var(--color-gray);
  --accent: var(--color-primary);
  --accent-secondary: var(--color-secondary);
  --accent-tertiary: var(--color-tertiary);
  --accent-foreground: var(--color-light);
  --hover-base: var(--color-gray-300);
  --hover-window: var(--color-dark-gray);
  --hover-panel: var(--color-gray-400);
  --hover-overlay: var(--color-gray-400);
  --hover-temporary: var(--color-dark-dark-gray-2);
  --cursor-default: url("../../semio/assets/cursors/cursor_dark.svg") 0 0, default;
  --cursor-pointer: url("../../semio/assets/cursors/cursor_pointer_dark_inkscape.svg") 0 0, pointer;
  --cursor-grab: url("../../semio/assets/cursors/cursor_grab_dark.svg") 0 0, grab;
  --cursor-grabbing: url("../../semio/assets/cursors/cursor_grabbing.svg") 0 0, grabbing;
  --cursor-ew-resize: url("../../semio/assets/cursors/cursor_ew-resize_dark.svg") 16 2, ew-resize;
  --cursor-col-resize: url("../../semio/assets/cursors/cursor_ew-resize_dark.svg") 16 2, col-resize;
  --cursor-ns-resize: url("../../semio/assets/cursors/cursor_ns-resize_dark.svg") 2 16, ns-resize;
  --cursor-nesw-resize: url("../../semio/assets/cursors/cursor_nesw-resize_dark.svg") 16 16, nesw-resize;
  --cursor-nwse-resize: url("../../semio/assets/cursors/cursor_nwse-resize_dark.svg") 16 16, nwse-resize;
  --cursor-move: url("../../semio/assets/cursors/cursor_move_dark.svg") 16 16, move;
  --cursor-crosshair: url("../../semio/assets/cursors/cursor_crosshair_dark.svg") 0 0, crosshair;
  --cursor-crosshair-centered: url("../../semio/assets/cursors/cursor_crosshair_dark.svg") 16 16, crosshair;
  --cursor-selectable: url("../../semio/assets/cursors/cursor_selectable_dark.svg") 0 0, pointer;
  --cursor-foldable: url("../../semio/assets/cursors/cursor_foldable_dark.svg") 0 0, pointer;
